        calibration_.biplane_calibration);
    trunk_manager_.UploadDistanceMap(&gpu_distance_maps_, &gpu_heatmaps_);
    branch_manager_.UploadDistanceMap(&gpu_distance_maps_, &gpu_heatmaps_);
