    gpu_principal_model_ = 0;
    /*Pointer to Vector of non-principal GPU Model Pointers*/
    gpu_non_principal_models_ = 0;

    /*GPU Metrics Initialize*/
    gpu_metrics_ = 0;

    /*Pose Storage Initialize*/
    pose_storage_ = 0;

    /*Initialize stage*/
    stage_ = Stage::Trunk;

